import React, { useState, useEffect } from "react";
import "./JumbleGame.css";

const JumbleGame = ({
  question,
  onAnswerSubmit,
  timer,
  answerSubmitted,
  showFeedback,
  isCorrectAnswer,
}) => {
  const [userAnswer, setUserAnswer] = useState("");

  useEffect(() => {
    if (!answerSubmitted) {
      setUserAnswer("");
    }
  }, [question, answerSubmitted]);

  // Auto-submit and validate when timer runs out
  useEffect(() => {
    if (timer === 0 && !answerSubmitted && userAnswer.trim()) {
      onAnswerSubmit(userAnswer);
    }
  }, [timer, answerSubmitted, userAnswer, onAnswerSubmit]);

  return (
    <div className="jumble-question">
      <h2>Unscramble the Word</h2>
      <div className="jumbled-word">{question.jumbled}</div>
      <input
        type="text"
        value={userAnswer}
        onChange={(e) => setUserAnswer(e.target.value)}
        placeholder="Enter the correct word"
        className="answer-input"
        disabled={answerSubmitted}
      />

      {!answerSubmitted ? (
        <button
          className="submit-btn"
          onClick={() => onAnswerSubmit(userAnswer)}
          disabled={!userAnswer.trim()}
        >
          Submit Answer
        </button>
      ) : (
        showFeedback && (
          <div
            className={`feedback ${isCorrectAnswer ? "correct" : "incorrect"}`}
          >
            {isCorrectAnswer ? (
              "Correct! 🎉"
            ) : (
              <div>
                <div>Incorrect answer</div>
                <div className="correct-answer">
                  The correct answer is: <strong>{question.answer}</strong>
                </div>
              </div>
            )}
          </div>
        )
      )}

      {/* Show correct answer when time runs out with no submission */}
      {timer === 0 &&
        !answerSubmitted &&
        !userAnswer.trim() &&
        showFeedback && (
          <div className="feedback incorrect">
            <div>Time's up! No answer submitted.</div>
            <div className="correct-answer">
              The correct answer is: <strong>{question.answer}</strong>
            </div>
          </div>
        )}
    </div>
  );
};

export default JumbleGame;
